209	/**
210	 * @param {import('../types/internal.ts').TemplateNode} node
211	 * @param {string} attr
212	 * @returns {AST.Text | AST.ExpressionTag | undefined}
213	 */
214	function get_attr_value(node, attr) {
215		if (!('type' in node) || !('attributes' in node)) return;
216		const attribute = node.attributes.find(
217			/** @param {any} v */ (v) => v.type === 'Attribute' && v.name === attr
218		);
219	
220		if (!attribute || !('value' in attribute) || typeof attribute.value === 'boolean') return;
221	
222		// Check if value is an array and has at least one element
223		if (Array.isArray(attribute.value)) {
224			if (attribute.value.length > 0) return attribute.value[0];
225			return;
226		}
227	
228		// If it's not an array or is empty, return the value as is
229		return attribute.value;
230	}
